  (222, true, '222|||טיפול קצר לילדי מילואימניקים 3-12 ומשפחות', '222|||פסיכותרפיה קצרה או ארוכה, לאדם ולקשרים הקרובים אליו. באוניברסיטה או בזום.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"centerf@biu.ac.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"אדוות להחלמה","svc":"פסיכותרפיה קצרה או ארוכה, לאדם ולקשרים הקרובים אליו. באוניברסיטה או בזום.","meeting":"both","target":"נפגעי טראומה ובני משפחותיהם","region":"רמת גן","founded":"","cost":"חלק מהטיפולים ללא עלות או במחיר מסובסד","specialty":"טראומה","approaches":"טיפול זוגי, טיפול משפחתי, טיפול הורה־ילד","notes":"בניין 417, אוניברסיטת בר־אילן.","web":"https://sites.biu.ac.il/ripples-recovery/page/7887"}'::jsonb, '{"org":"Ripples for Recovery","svc":"Psychotherapy, short or long, for the person and for the close relationships around them. At the university or on Zoom.","target":"People affected by trauma and their families","region":"Ramat Gan","founded":"","cost":"Some of the treatment is at no cost or at a subsidized price","specialty":"Trauma","approaches":"Couples therapy, family therapy, parent-child therapy","notes":"Building 417, Bar-Ilan University.","meeting":"both","email":"centerf@biu.ac.il","emailLabel":"Email","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://sites.biu.ac.il/ripples-recovery/page/7887 ו-https://social-work.biu.ac.il/couples_post_trauma. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (226, true, '226|||עד 12 מפגשים טיפול רגשי ללא עלות', '226|||טיפול מקוון במצוקה נפשית, על ידי פסיכולוגים ופסיכיאטרים של שיבא. מרחוק.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"שיבא BEYOND","svc":"טיפול מקוון במצוקה נפשית, על ידי פסיכולוגים ופסיכיאטרים של שיבא. מרחוק.","meeting":"","target":"מבוגרים וילדים","region":"כל הארץ","founded":"","cost":"","specialty":"","approaches":"","notes":"","web":"https://eng.sheba.co.il/199353"}'::jsonb, '{"org":"Sheba BEYOND","svc":"Online care for mental distress, by Sheba psychologists and psychiatrists. Remotely.","target":"Adults and children","region":"Nationwide","founded":"","cost":"","specialty":"","approaches":"","notes":"","meeting":"","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://eng.sheba.co.il/199353. בדף לא מופיעים 12 מפגשים או 072-3553026. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (228, true, '228|||טיפול, ליווי ושיקום — רשפון', '228|||טיפולי גוף־נפש וסדנאות חוסן לנפגעי טראומה. בחווה.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"groups@healingspace.co.il","emailLabel":"קבוצות","emailShowAddress":false,"email2":"info@healingspace.co.il","emailLabel2":"פניות","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"חוות מרפא","svc":"טיפולי גוף־נפש וסדנאות חוסן לנפגעי טראומה. בחווה.","meeting":"in_person","target":"יחידים וקהילות","region":"רשפון","founded":"","cost":"","specialty":"טראומה","approaches":"טיפולי גוף־נפש, סדנאות חוסן","notes":"הפרדס 48."}'::jsonb, '{"org":"Healing Space","svc":"Mind-body treatment and resilience workshops for people affected by trauma. At the farm.","target":"Individuals and communities","region":"Rishpon","founded":"","cost":"","specialty":"Trauma","approaches":"Mind-body treatment, resilience workshops","notes":"48 HaPardes St.","meeting":"in_person","email":"groups@healingspace.co.il","emailLabel":"Groups","email2":"info@healingspace.co.il","emailLabel2":"Inquiries","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://healingspace.co.il/ ו-https://healingspace.co.il/contact/. המספר 074-7556155 אינו בדף יצירת הקשר. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (229, true, '229|||מוקד סיוע רגשי מרחוק (מגיל 12) — עברית, ערבית, רוסית, אנגלית', '229|||מענה רגשי טיפולי ממוקד בטלפון, עד 12 שיחות. בטלפון.', '{"phone":"04-6900603","phoneLabel":"עברית","phoneShowNumber":false,"phone2":"04-7702649","phoneLabel2":"ערבית","phoneShowNumber2":false,"phone3":"04-7702650","phoneLabel3":"רוסית","phoneShowNumber3":false,"phone4":"04-7702651","phoneLabel4":"אנגלית","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"מרכז משאבים","svc":"מענה רגשי טיפולי ממוקד בטלפון, עד 12 שיחות. בטלפון.","meeting":"","target":"תושבי הגליל המערבי, המזרחי והגולן","region":"גליל מערבי, גליל מזרחי, גולן","founded":"","cost":"ללא עלות","specialty":"לחץ, חרדה","approaches":"","notes":"","web":"https://icspc.org/help-lines/"}'::jsonb, '{"org":"The Mashabim Center","svc":"Focused emotional treatment by phone, up to 12 calls. By phone.","target":"Residents of the western Galilee, the eastern Galilee, and the Golan","region":"Western Galilee, eastern Galilee, the Golan","founded":"","cost":"At no cost","specialty":"Stress, anxiety","approaches":"","notes":"","meeting":"","phone":"04-6900603","phoneLabel":"Hebrew","phone2":"04-7702649","phoneLabel2":"Arabic","phone3":"04-7702650","phoneLabel3":"Russian","phone4":"04-7702651","phoneLabel4":"English","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://icspc.org/help-lines/. טופס גוגל הישן הוא טופס פנייה, לא דף המוקד. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (230, true, '230|||תמיכה רגשית לצעירים 17-27 בחוות שמש — ללא עלות', '230|||המרחב נסגר לעת עתה. נשארה תוכנית בימי חמישי ללוחמים ולחיילים משוחררים שאינם מוכרים באגף השיקום.', '{"phone":"*9056","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"חיבוק ברזל","svc":"המרחב נסגר לעת עתה. נשארה תוכנית בימי חמישי ללוחמים ולחיילים משוחררים שאינם מוכרים באגף השיקום.","meeting":"","target":"","region":"גבעת שמש","founded":"","cost":"","specialty":"","approaches":"","notes":"","web":"https://www.ironhug.co.il/"}'::jsonb, '{"org":"Iron Hug","svc":"The space is closed for now. A Thursday program remains for combat soldiers and discharged soldiers who are not recognized by the Rehabilitation Department.","target":"","region":"Givat Shemesh","founded":"","cost":"","specialty":"","approaches":"","notes":"","meeting":"","phone":"*9056","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.ironhug.co.il/. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (232, true, '232|||מאגר תחנות לטיפול זוגי', '232|||רשימת תחנות ציבוריות לטיפול זוגי ומשפחתי, בפיקוח משרד הרווחה.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"האגודה הישראלית לטיפול זוגי ומשפחתי","svc":"רשימת תחנות ציבוריות לטיפול זוגי ומשפחתי, בפיקוח משרד הרווחה.","meeting":"","target":"","region":"כל הארץ","founded":"","cost":"","specialty":"","approaches":"","notes":"","web":"https://mishpaha.org.il/%D7%90%D7%99%D7%AA%D7%95%D7%A8-%D7%9E%D7%98%D7%A4%D7%9C-%D7%96%D7%95%D7%92%D7%99-%D7%95%D7%9E%D7%A9%D7%A4%D7%97%D7%AA%D7%99-%D7%9E%D7%95%D7%A1%D7%9E%D7%9A-2/%D7%AA%D7%97%D7%A0%D7%95%D7%AA-%D7%A6%D7%99%D7%91%D7%95%D7%A8%D7%99%D7%95%D7%AA-%D7%9C%D7%99%D7%99%D7%A2%D7%95%D7%A5-%D7%91%D7%97%D7%99%D7%99-%D7%94%D7%A0%D7%99%D7%A9%D7%95%D7%90%D7%99%D7%9F-%D7%95/"}'::jsonb, '{"org":"The Israeli Association for Couples and Family Therapy","svc":"A list of public stations for couples and family therapy, under the Ministry of Welfare.","target":"","region":"Nationwide","founded":"","cost":"","specialty":"","approaches":"","notes":"","meeting":"","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול דף התחנות באתר האגודה, mishpaha.org.il. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (233, true, '233|||סיוע וטיפול לשורדי המסיבות בנובה — הרצליה', '233|||מרכז יום לשורדי המסיבות ולבני משפחותיהם בהרצליה. פעל עד יולי 2025.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"איזון ארנה","svc":"מרכז יום לשורדי המסיבות ולבני משפחותיהם בהרצליה. פעל עד יולי 2025.","meeting":"","target":"","region":"הרצליה","founded":"","cost":"","specialty":"","approaches":"","notes":"","web":"https://izun.org.il/"}'::jsonb, '{"org":"Izun Arena","svc":"A day center in Herzliya for party survivors and their families. It ran until July 2025.","target":"","region":"Herzliya","founded":"","cost":"","specialty":"","approaches":"","notes":"","meeting":"","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://izun.org.il/. בפתיח כתוב שהמרכז פעל עד יולי 2025. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (234, true, '234|||טיפול עומק לפצועי נובה — לפחות 24 מפגשים', '234|||טיפול נפשי ארוך טווח לשורדי המסיבות ולבני משפחותיהם. אצל מטפל קרוב לבית, וגם בקבוצה.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@safeheartil.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"לב בטוח (SafeHeart)","svc":"טיפול נפשי ארוך טווח לשורדי המסיבות ולבני משפחותיהם. אצל מטפל קרוב לבית, וגם בקבוצה.","meeting":"","target":"שורדי המסיבות בעוטף עזה ובני משפחותיהם","region":"כל הארץ","founded":"2023","cost":"ללא עלות","specialty":"טראומה","approaches":"","notes":"אפשר לפנות גם אם לא היה שימוש בחומרים. יש גם קבוצות, ריטריטים וליווי למשפחות.","web":"https://www.safeheartil.com/"}'::jsonb, '{"org":"SafeHeart","svc":"Long-term mental-health care for party survivors and their families. With a therapist near home, and also in a group.","target":"Survivors of the parties in the Gaza envelope and their families","region":"Nationwide","founded":"2023","cost":"At no cost","specialty":"Trauma","approaches":"","notes":"You can turn to them even if no substances were used. There are also groups, retreats, and support for families.","meeting":"","email":"info@safeheartil.com","emailLabel":"Email","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.safeheartil.com/. המספר 24 בדף הוא נתון, לא אורך טיפול. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (235, true, '235|||טיפול ממוקד בטראומה לשורדי מסיבות — מרכז רפואי + מסיבות בדרום', '235|||פסיכותרפיה, עם מעקב פסיכיאטרי, להפרעת דחק פוסט־טראומטית. במרפאה.', '{"phone":"09-8980474","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"litalmalachi@lev-hasharon.co.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"המרפאה לשורדי נובה ומסיבות הטבע, לב השרון","svc":"פסיכותרפיה, עם מעקב פסיכיאטרי, להפרעת דחק פוסט־טראומטית. במרפאה.","meeting":"in_person","target":"שורדי המסיבות ברעים, ובני משפחה בוגרים לפי הערכה","region":"צור משה","founded":"","cost":"קופת החולים, עם טופס 17","specialty":"PTSD","approaches":"טיפול פרטני, טיפול קבוצתי","notes":"השיבולים, מבנה עוגן. יום טיפולי בימי שלישי. כשנה, לפי הערכה. קוד L0771.","web":"https://www.lev-hasharon.co.il/?clinic=%D7%94%D7%9E%D7%A8%D7%A4%D7%90%D7%94-%D7%9C%D7%98%D7%99%D7%A4%D7%95%D7%9C-%D7%91%D7%A9%D7%95%D7%A8%D7%93%D7%99-%D7%A0%D7%95%D7%91%D7%94-%D7%95%D7%9E%D7%A1%D7%99%D7%91%D7%95%D7%AA-%D7%94%D7%98%D7%91"}'::jsonb, '{"org":"The clinic for Nova and nature-party survivors, Lev Hasharon","svc":"Psychotherapy, with psychiatric follow-up, for post-traumatic stress disorder. At the clinic.","target":"Survivors of the parties at Reim, and adult family members after an assessment","region":"Tzur Moshe","founded":"","cost":"The health fund, with Form 17","specialty":"PTSD","approaches":"Individual therapy, group therapy","notes":"HaShibolim St, Ogen building. A treatment day on Tuesdays. About a year, according to the assessment. Code L0771.","meeting":"in_person","phone":"09-8980474","phoneLabel":"Phone","email":"litalmalachi@lev-hasharon.co.il","e