  (243, true, '243|||3 שיחות טיפוליות מקוונות ללא עלות', '243|||מוקד תמיכה נפשית, וגם 3 שיחות טיפוליות. בטלפון.', '{"phone":"*8703","phoneLabel":"כללית","phoneShowNumber":false,"phone2":"*3555","phoneLabel2":"מכבי","phoneShowNumber2":false,"phone3":"*3833","phoneLabel3":"מאוחדת","phoneShowNumber3":false,"phone4":"*507","phoneLabel4":"לאומית","phoneShowNumber4":false,"phone5":"*3028","phoneLabel5":"מכבי, שיחות","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"קווי תמיכה נפשית, קופות החולים","svc":"מוקד תמיכה נפשית, וגם 3 שיחות טיפוליות. בטלפון.","meeting":"","target":"","region":"כל הארץ","founded":"","cost":"במסגרת קופת החולים","specialty":"","approaches":"","notes":"","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/crisis-support/first-aid/"}'::jsonb, '{"org":"Mental-health support lines, health funds","svc":"A mental-health support line, and also 3 treatment calls. By phone.","target":"","region":"Nationwide","founded":"","cost":"Through the health fund","specialty":"","approaches":"","notes":"","meeting":"","phone":"*8703","phoneLabel":"Clalit","phone2":"*3555","phoneLabel2":"Maccabi","phone3":"*3833","phoneLabel3":"Meuhedet","phone4":"*507","phoneLabel4":"Leumit","phone5":"*3028","phoneLabel5":"Maccabi, treatment calls","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://me.health.gov.il/mental-health/therapy-rehabilitation/crisis-support/first-aid/ ודף המוקדים של מכבי. *3028 נשאר כי מכבי מפרסמת אותו לשיחות הטיפול. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (282, true, '282|||מרכז יום לנוער וצעירים (12–35) על רצף הטראומה וההתמכרות — אבחון, טיפול פרטני וקבוצתי וליווי שיקומי', '282|||מרכז יום לנוער ולצעירים על רצף הטראומה וההתמכרות: אבחון, טיפול פרטני וקבוצתי, וליווי שיקומי. במרכז או מרחוק.', '{"phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"מרכז צ׳ויס (CHOICE)","svc":"מרכז יום לנוער ולצעירים על רצף הטראומה וההתמכרות: אבחון, טיפול פרטני וקבוצתי, וליווי שיקומי. במרכז או מרחוק.","meeting":"both","target":"נוער וצעירים 12–35","region":"בני ברק, כל הארץ","founded":"","cost":"","specialty":"טראומה, התמכרות","approaches":"","notes":"בר־כוכבא 23, קומה 5, בני ברק."}'::jsonb, '{"org":"CHOICE Center","svc":"A day center for youth and young adults on the trauma and addiction continuum: assessment, individual and group treatment, and rehabilitation support. At the center or remotely.","target":"Youth and young adults, ages 12-35","region":"Bnei Brak, nationwide","founded":"","cost":"","specialty":"Trauma, addiction","approaches":"","notes":"23 Bar Kochba St, 5th floor, Bnei Brak.","meeting":"both","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול דף CHOICE באתר האגודה לבריאות הציבור. גוף הדף עדיין בלשון עתיד, ובשורה נכתב שהמרכז נפתח. הניסוח אושר עם אצוות הטראומה השנייה.'),
  (290, true, '290|||קליניקה לטיפול בנשים ובנערות — פסיכותרפיה, פגיעות מיניות, הפרעות אכילה, דיכאון אחרי לידה ואלימות ביחסים', '290|||פסיכותרפיה לנשים ולנערות.', '{"phone":"050-4080498","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@wtc-anatgur.co.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"חכמת נשים","svc":"פסיכותרפיה לנשים ולנערות.","meeting":"","target":"נשים ונערות","region":"","founded":"","cost":"","specialty":"הפרעות אכילה, פגיעות מיניות, דיכאון אחרי לידה, אלימות ביחסים","approaches":"טיפול פרטני, טיפול קבוצתי, טיפול באומנות, טיפול דיאדי","notes":"בהנהלת ד״ר ענת גור. יש שלוחות בירושלים, בחיפה ובצפון. גברים וזוגות יכולים לפנות כשמדובר באלימות ביחסים, ויש גם מענה לילדים שנפגעו מינית. מסגרות הדיור בכרטיס נפרד."}'::jsonb, '{"org":"Chochmat Nashim","svc":"Psychotherapy for women and girls.","target":"Women and girls","region":"","founded":"","cost":"","specialty":"Eating disorders, sexual abuse, postpartum depression, violence in relationships","approaches":"Individual therapy, group therapy, art therapy, dyadic therapy","notes":"Directed by Dr. Anat Gur. There are branches in Jerusalem, Haifa, and the north. Men and couples can turn to the clinic when the issue is violence in the relationship, and there is also care for children who were sexually abused. The housing programs are on a separate card.","meeting":"","phone":"050-4080498","phoneLabel":"Phone","email":"info@wtc-anatgur.co.il","emailLabel":"Email","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","em