  (771, true, '771|||רכיבת הרים טיפולית ללוחמים ומילואימניקים', '771|||רכיבת הרים טיפולית ללוחמים ולמילואימניקים. במפגש שבועי.', '{"phone":"058-766-2212","phoneLabel":"מרים","phoneShowNumber":false,"phone2":"052-772-3500","phoneLabel2":"משרד","phoneShowNumber2":false,"phone3":"052-452-2891","phoneLabel3":"משרד","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"miriam@geerz.org","emailLabel":"מרים","emailShowAddress":false,"email2":"admin@geerz.org","emailLabel2":"משרד","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"גירז (Geerz)","svc":"רכיבת הרים טיפולית ללוחמים ולמילואימניקים. במפגש שבועי.","meeting":"in_person","target":"לוחמים ומילואימניקים קרביים, גם בלי אבחנה","region":"","founded":"2012","cost":"אפשר לשלם ממענק הטיפולים האישי","specialty":"","approaches":"","notes":"16 מפגשים של שעתיים. בחלק מהקבוצות אין צורך בניסיון, והאופניים ניתנים למשך התוכנית. פיילוט בשבי דרום. קבוצה נוספת לפי בקשה. נחל מטה 14/2, בית שמש. קבוצות הילדים והנוער בכרטיס נפרד."}'::jsonb, '{"org":"Geerz","svc":"Therapeutic mountain biking for combat soldiers and reservists. At a weekly meeting.","target":"Combat soldiers and reservists, with or without a diagnosis","region":"","founded":"2012","cost":"It can be paid from the personal treatment grant","specialty":"","approaches":"","notes":"16 sessions of two hours. Some groups need no experience, and the bike is provided for the program. A pilot in Shavei Darom. Another group opens on request. 14/2 Nahal Mata, Beit Shemesh. The children and youth groups are on a separate card.","meeting":"in_person","phone":"058-766-2212","phoneLabel":"Miriam","phone2":"052-772-3500","phoneLabel2":"Office","phone3":"052-452-2891","phoneLabel3":"Office","email":"miriam@geerz.org","emailLabel":"Miriam","email2":"admin@geerz.org","emailLabel2":"Office","phone4":"","phoneLabel4":""