  (772, true, '772|||ריטריט בטבע ללוחמים קרביים', '772|||ריטריט של שבוע בטבע ללוחמים קרביים, בקבוצה מהיחידה. בטבע.', '{"phone":"054-203-0339","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"contact@hin-group.org","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"org":"Healing in Nature","svc":"ריטריט של שבוע בטבע ללוחמים קרביים, בקבוצה מהיחידה. בטבע.","meeting":"in_person","target":"לוחמים קרביים, בקבוצה מהיחידה","region":"","founded":"","cost":"","specialty":"טראומה","approaches":"רכיבה טיפולית","notes":"אחר כך קהילת בוגרים. ליווי מחקרי עם אוניברסיטת תל אביב וקיימברידג׳. בצוות פסיכיאטר ופסיכולוגית קלינית. משרד העמותה: חוט השני 1, מודיעין."}'::jsonb, '{"org":"Healing in Nature","svc":"A one-week retreat in nature for combat soldiers, in a group from the unit. In nature.","target":"Combat soldiers, in a group from the unit","region":"","founded":"","cost":"","specialty":"Trauma","approaches":"Therapeutic riding","notes":"Afterwards, a community of graduates. Research accompaniment with Tel Aviv University and Cambridge. The team includes a psychiatrist and a clinical psychologist. The nonprofit office: 1 Chut HaShani, Modiin.","meeting":"in_person","phone":"054-203-0339","phoneLabel":"Phone","email":"contact@hin-group.org","emailLabel":"Email","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.hin-group.org/ ודף התנאים. המשרד במודיעין אינו מקום הריטריט. הניסוח אושר עם אצוות הטראומה השנייה.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM trauma_wording_2 w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN trauma_wording_2 w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM trauma_wording_2 w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN trauma_wording_2 w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

